**Modular Real-Time Chat Server in C#**
=====================================

### Overview

This implementation consists of three isolated components:

1. **TCP Connection Manager**: Handles client handshakes and keep-alive heartbeats.
2. **Room Management Subsystem**: Supports channel creation, broadcasting, and user permission roles.
3. **Message Persistence Engine**: Asynchronously buffers chat history to a relational store.

### TCP Connection Manager

#### ConnectionManager.cs
```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

public class ConnectionManager
{
    private readonly TcpListener _listener;
    private readonly Logger _logger;
    private readonly RoomManager _roomManager;

    public ConnectionManager(int port, RoomManager roomManager, Logger logger)
    {
        _listener = new TcpListener(IPAddress.Any, port);
        _roomManager = roomManager;
        _logger = logger;
    }

    public async Task Start()
    {
        _listener.Start();
        _logger.Info("Connection Manager started.");

        while (true)
        {
            var client = await _listener.AcceptTcpClientAsync();
            _logger.Info($"Client connected from {client.Client.RemoteEndPoint}.");

            var clientHandler = new ClientHandler(client, _roomManager);
            await Task.Run(async () => await clientHandler.HandleClient());
        }
    }
}

public class ClientHandler
{
    private readonly TcpClient _client;
    private readonly RoomManager _roomManager;

    public ClientHandler(TcpClient client, RoomManager roomManager)
    {
        _client = client;
        _roomManager = roomManager;
    }

    public async Task HandleClient()
    {
        // Handle client handshake and keep-alive heartbeats
        await SendWelcomeMessage();
        await StartKeepAliveLoop();
    }

    private async Task SendWelcomeMessage()
    {
        // Send welcome message to client
        var welcomeMessage = "Welcome to the chat server!";
        var buffer = Encoding.UTF8.GetBytes(welcomeMessage);
        await _client.GetStream().WriteAsync(buffer, 0, buffer.Length);
    }

    private async Task StartKeepAliveLoop()
    {
        while (true)
        {
            // Send keep-alive heartbeat to client
            var heartbeatMessage = "Keep-alive";
            var buffer = Encoding.UTF8.GetBytes(heartbeatMessage);
            await _client.GetStream().WriteAsync(buffer, 0, buffer.Length);

            // Wait for 1 minute before sending next heartbeat
            await Task.Delay(TimeSpan.FromMinutes(1));
        }
    }
}
```

### Room Management Subsystem

#### RoomManager.cs
```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

public class RoomManager
{
    private readonly ConcurrentDictionary<string, Room> _rooms;

    public RoomManager()
    {
        _rooms = new ConcurrentDictionary<string, Room>();
    }

    public Room CreateRoom(string name)
    {
        // Create a new room and add it to the dictionary
        var room = new Room(name);
        _rooms.TryAdd(name, room);
        return room;
    }

    public Room GetRoom(string name)
    {
        // Get a room from the dictionary
        _rooms.TryGetValue(name, out var room);
        return room;
    }

    public void DeleteRoom(string name)
    {
        // Remove a room from the dictionary
        _rooms.TryRemove(name, out _);
    }

    public void BroadcastMessage(string roomName, string message)
    {
        // Broadcast a message to all users in the room
        var room = GetRoom(roomName);
        if (room != null)
        {
            room.BroadcastMessage(message);
        }
    }
}

public class Room
{
    private readonly List<User> _users;
    private readonly string _name;

    public Room(string name)
    {
        _name = name;
        _users = new List<User>();
    }

    public void AddUser(User user)
    {
        // Add a user to the room
        _users.Add(user);
    }

    public void RemoveUser(User user)
    {
        // Remove a user from the room
        _users.Remove(user);
    }

    public void BroadcastMessage(string message)
    {
        // Broadcast a message to all users in the room
        foreach (var user in _users)
        {
            user.ReceiveMessage(message);
        }
    }
}

public class User
{
    private readonly string _username;
    private readonly string _roomName;

    public User(string username, string roomName)
    {
        _username = username;
        _roomName = roomName;
    }

    public void ReceiveMessage(string message)
    {
        // Receive a message from the room
        Console.WriteLine($"User {_username} received message: {message}");
    }
}
```

### Message Persistence Engine

#### MessagePersister.cs
```csharp
using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class MessagePersister
{
    private readonly string _connectionString;

    public MessagePersister(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task SaveMessageAsync(string roomName, string message)
    {
        // Save a message to the database
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("INSERT INTO Messages (RoomName, Message) VALUES (@roomName, @message)", connection);
            command.Parameters.AddWithValue("@roomName", roomName);
            command.Parameters.AddWithValue("@message", message);
            await command.ExecuteNonQueryAsync();
        }
    }

    public async Task SaveMessagesAsync(List<Message> messages)
    {
        // Save multiple messages to the database
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var transaction = connection.BeginTransaction();
            foreach (var message in messages)
            {
                var command = new SqlCommand("INSERT INTO Messages (RoomName, Message) VALUES (@roomName, @message)", connection, transaction);
                command.Parameters.AddWithValue("@roomName", message.RoomName);
                command.Parameters.AddWithValue("@message", message.Message);
                await command.ExecuteNonQueryAsync();
            }
            transaction.Commit();
        }
    }
}

public class Message
{
    public string RoomName { get; set; }
    public string Message { get; set; }
}
```

### Example Usage

```csharp
class Program
{
    static async Task Main(string[] args)
    {
        // Create a new room manager
        var roomManager = new RoomManager();

        // Create a new room
        var room = roomManager.CreateRoom("MyRoom");

        // Create a new user
        var user = new User("JohnDoe", "MyRoom");

        // Add the user to the room
        room.AddUser(user);

        // Broadcast a message to the room
        roomManager.BroadcastMessage("MyRoom", "Hello, world!");

        // Create a new message persister
        var messagePersister = new MessagePersister("Server=MyServer;Database=MyDatabase;User Id=MyUser;Password=MyPassword;");

        // Save a message to the database
        await messagePersister.SaveMessageAsync("MyRoom", "Hello, world!");

        // Create a new connection manager
        var connectionManager = new ConnectionManager(12345, roomManager, new Logger());

        // Start the connection manager
        await connectionManager.Start();
    }
}
```

### Notes

* This implementation uses a simple relational database to store chat history.
* The `MessagePersister` class uses ADO.NET to interact with the database.
* The `RoomManager` class uses a concurrent dictionary to store rooms and users.
* The `ConnectionManager` class uses a TCP listener to accept client connections.
* The `ClientHandler` class handles client handshakes and keep-alive heartbeats.
* This implementation does not handle disconnections or errors.
* This implementation does not implement user authentication or authorization.
* This implementation does not implement room permission roles.
* This implementation does not implement message editing or deletion.
* This implementation does not implement file sharing or other advanced features.
